public List<List<Integer>> permute(int[] nums) {
    java.util.List<java.util.List<Integer>> res = new java.util.ArrayList<>();
    if (nums == null) return res;
    int n = nums.length;
    if (n == 0) {
        res.add(new java.util.ArrayList<>());
        return res;
    }
    boolean[] used = new boolean[n];
    java.util.List<Integer> current = new java.util.ArrayList<>();
    class Backtrack {
        void dfs() {
            if (current.size() == n) {
                res.add(new java.util.ArrayList<>(current));
                return;
            }
            for (int i = 0; i < n; i++) {
                if (!used[i]) {
                    used[i] = true;
                    current.add(nums[i]);
                    dfs();
                    current.remove(current.size() - 1);
                    used[i] = false;
                }
            }
        }
    }
    new Backtrack().dfs();
    return res;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    List<Set<String>> sets = new ArrayList<>();
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        Set<String> set = new HashSet<>();
        int len = s.length();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                String sub = s.substring(i, j);
                set.add(sub);
                set.add(new StringBuilder(sub).reverse().toString());
            }
        }
        sets.add(set);
    }
    Set<String> intersection = new HashSet<>(sets.get(0));
    for (int i = 1; i < sets.size(); i++) {
        intersection.retainAll(sets.get(i));
        if (intersection.isEmpty()) {
            return 0;
        }
    }
    int maxLen = 0;
    for (String str : intersection) {
        if (str.length() > maxLen) {
            maxLen = str.length();
        }
    }
    return maxLen;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }
    int rows = grid.length;
    int count = 0;
    boolean[][] visited = new boolean[rows][];
    for (int i = 0; i < rows; i++) {
        visited[i] = new boolean[grid[i].length];
    }
    int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                count++;
                java.util.Deque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{i, j});
                visited[i][j] = true;
                while (!stack.isEmpty()) {
                    int[] cur = stack.pop();
                    int x = cur[0];
                    int y = cur[1];
                    for (int dir = 0; dir < 8; dir++) {
                        int nx = x + dx[dir];
                        int ny = y + dy[dir];
                        if (nx >= 0 && nx < rows && ny >= 0 && ny < grid[nx].length) {
                            if (!visited[nx][ny] && grid[nx][ny] == '@') {
                                visited[nx][ny] = true;
                                stack.push(new int[]{nx, ny});
                            }
                        }
                    }
                }
            }
        }
    }
    return count;
}

