public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : numbers) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int count = 0;
    for (int num : numbers) {
        if (num % 2 != 0) {
            continue;
        }
        int half = num / 2;
        Integer halfCount = freq.get(half);
        if (halfCount == null) {
            continue;
        }
        if (half != num || halfCount > 1) {
            count++;
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate basic parameters
    if (n <= 0) return "cannot be travelled";
    if (start == null || end == null || start.length != 2 || end.length != 2) return "cannot be travelled";
    int sx = start[0], sy = start[1];
    int ex = end[0], ey = end[1];
    if (sx < 0 || sx >= n || sy < 0 || sy >= n || ex < 0 || ex >= n || ey < 0 || ey >= n) return "cannot be travelled";
    if (sx == ex && sy == ey) return "can be travelled";

    // Build adjacency map for the grid intersections
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    if (paths != null) {
        for (int[] p : paths) {
            if (p == null || p.length != 4) continue;
            int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
            if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) continue;
            String a = x1 + "," + y1;
            String b = x2 + "," + y2;
            adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
            adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
        }
    }

    // Breadth‑first search from start to end
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    String startKey = sx + "," + sy;
    String endKey = ex + "," + ey;
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                if (nb.equals(endKey)) return "can be travelled";
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        return null;
    }
    try {
        java.time.format.DateTimeFormatter inputFormatter =
                java.time.format.DateTimeFormatter.ofPattern("M d yyyy", java.util.Locale.ENGLISH);
        java.time.LocalDate localDate = java.time.LocalDate.parse(date.trim(), inputFormatter);

        java.time.format.DateTimeFormatter outputFormatter =
                java.time.format.DateTimeFormatter.ofPattern("MMMM d, yyyy", java.util.Locale.ENGLISH);
        String formattedDate = localDate.format(outputFormatter);

        String weekday = localDate.getDayOfWeek()
                .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        return formattedDate + " is a " + weekday;
    } catch (java.time.format.DateTimeParseException e) {
        return null;
    }
}

public int[] twoSum(int[] nums, int target) {
    if (nums == null || nums.length < 2) {
        return new int[]{-1, -1};
    }
    java.util.HashMap<Integer, Integer> map = new java.util.HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (map.containsKey(complement)) {
            return new int[]{map.get(complement), i};
        }
        map.put(nums[i], i);
    }
    return new int[]{-1, -1};
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        // Determine which side is sorted
        if (nums[left] <= nums[mid]) { // left side is sorted
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else { // right side is sorted
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

