public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    if (arr.length % 2 != 0) {
        return false;
    }
    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        count[r]++;
    }
    if (count[0] % 2 != 0) {
        return false;
    }
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // k even and r == k/2
            if (count[r] % 2 != 0) {
                return false;
            }
        } else {
            if (count[r] != count[k - r]) {
                return false;
            }
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || hasApple == null || hasApple.length != n) {
        return 0;
    }
    // Build adjacency list
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    if (edges != null) {
        for (int[] e : edges) {
            if (e == null || e.length < 2) continue;
            int u = e[0];
            int v = e[1];
            if (u < 0 || u >= n || v < 0 || v >= n) continue;
            graph[u].add(v);
            graph[v].add(u);
        }
    }
    // If no edges and only one node, no traversal needed
    if (n == 1) {
        return 0;
    }
    int[] time = {0};
    // DFS to accumulate time
    java.util.function.BiFunction<Integer, Integer, Boolean> dfs = new java.util.function.BiFunction<>() {
        @Override
        public Boolean apply(Integer node, Integer parent) {
            boolean has = hasApple[node];
            for (int nei : graph[node]) {
                if (nei == parent) continue;
                if (apply(nei, node)) {
                    time[0] += 2;
                    has = true;
                }
            }
            return has;
        }
    };
    dfs.apply(0, -1);
    return time[0];
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s == null ? null : "";
    }
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        if (c >= 'a' && c <= 'z') {
            freq[c - 'a']++;
        } else {
            // If the string may contain characters outside 'a'-'z', treat them as is
            // by expanding the frequency array or handling separately.
            // For simplicity, we ignore them in this implementation.
        }
    }
    StringBuilder result = new StringBuilder(s.length());
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending pass: pick smallest available characters
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
        // Descending pass: pick largest available characters
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // dp[k] holds all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new HashSet<>();
    }
    dp[0].add(0);
    for (int num : nums) {
        // iterate k from current max down to 1 to avoid reuse of the same element
        for (int k = n - 1; k >= 0; k--) {
            if (dp[k].isEmpty()) continue;
            for (int sum : dp[k]) {
                dp[k + 1].add(sum + num);
            }
        }
    }
    // Check for any k where average can be matched
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Can start at step 1 (top) without paying any cost
        return 0;
    }
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null || words.length == 0) {
        return 0;
    }
    String[] morse = {".-","-...","-.-.","-..",".","..-.","--.","....","..",
                      ".---","-.-",".-..","--","-.","---",".--.","--.-",".-.",
                      "...","-","..-","...-",".--","-..-","-.--","--.."};
    java.util.Set<String> set = new java.util.HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (c >= 'a' && c <= 'z') {
                sb.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') {
                sb.append(morse[c - 'A']);
            } // ignore non-letter characters
        }
        set.add(sb.toString());
    }
    return set.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) return false;
    int n = s.length();
    if (n < k) return false;
    long total = 1L << k;
    if (total > Integer.MAX_VALUE) return false; // too many codes to track
    java.util.HashSet<Integer> seen = new java.util.HashSet<>();
    int mask = (1 << k) - 1;
    int code = 0;
    for (int i = 0; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            seen.add(code);
            if (seen.size() == total) return true;
        }
    }
    return seen.size() == total;
}

