public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    long currentMax = 0;
    long currentMin = 0;
    long globalMax = Long.MIN_VALUE;
    long globalMin = Long.MAX_VALUE;
    for (int num : nums) {
        currentMax = Math.max(num, currentMax + num);
        globalMax = Math.max(globalMax, currentMax);
        currentMin = Math.min(num, currentMin + num);
        globalMin = Math.min(globalMin, currentMin);
    }
    long result = Math.max(globalMax, -globalMin);
    return (int) result;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }
    // Generate Fibonacci numbers up to k
    int[] fibs = new int[50]; // 50 is more than enough for int range
    fibs[0] = 1;
    fibs[1] = 1;
    int size = 2;
    while (true) {
        long next = (long) fibs[size - 1] + fibs[size - 2];
        if (next > k) {
            break;
        }
        fibs[size++] = (int) next;
    }

    int remaining = k;
    int count = 0;
    while (remaining > 0) {
        // Find the largest Fibonacci number <= remaining
        int idx = size - 1;
        while (fibs[idx] > remaining) {
            idx--;
        }
        remaining -= fibs[idx];
        count++;
    }
    return count;
}

public int kthFactor(int n, int k) {
    // Validate input
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int counterpart = n / i;
            if (counterpart != i) {
                large.add(counterpart);
            }
        }
    }
    // Combine small factors and reversed large factors
    java.util.ArrayList<Integer> allFactors = new java.util.ArrayList<>(small.size() + large.size());
    allFactors.addAll(small);
    for (int i = large.size() - 1; i >= 0; i--) {
        allFactors.add(large.get(i));
    }
    if (k > allFactors.size()) {
        return -1;
    }
    return allFactors.get(k - 1);
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (char c : s.toCharArray()) {
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            if (Math.abs(c - top) == 32) { // 'a' - 'A' == 32
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    return dfs(s, 0, new java.util.HashSet<String>());
}

private int dfs(String s, int start, java.util.Set<String> used) {
    if (start == s.length()) {
        return used.size();
    }
    int best = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String sub = s.substring(start, end);
        if (!used.contains(sub)) {
            used.add(sub);
            int res = dfs(s, end, used);
            if (res > best) {
                best = res;
            }
            used.remove(sub);
        }
    }
    return best;
}

public int minOperations(String[] logs) {
