    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    java.util.Set<Long> visited = new java.util.HashSet<>();
    for (int i = 0; i <= 9; i++) {
        if (i > high) break;
        queue.offer((long) i);
        visited.add((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) continue;
        if (num >= lower) {
            result.add((int) num);
        }
        int lastDigit = (int) (num % 10);
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high && !visited.contains(next)) {
                queue.offer(next);
                visited.add(next);
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high && !visited.contains(next)) {
                queue.offer(next);
                visited.add(next);
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("num must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] dpH = new int[m][n]; // horizontal
    int[][] dpV = new int[m][n]; // vertical
    int[][] dpD = new int[m][n]; // diagonal (top-left to bottom-right)
    int[][] dpA = new int[m][n]; // anti-diagonal (top-right to bottom-left)
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dpH[i][j] = (j > 0 ? dpH[i][j - 1] : 0) + 1;
                dpV[i][j] = (i > 0 ? dpV[i - 1][j] : 0) + 1;
                dpD[i][j] = (i > 0 && j > 0 ? dpD[i - 1][j - 1] : 0) + 1;
                dpA[i][j] = (i > 0 && j < n - 1 ? dpA[i - 1][j + 1] : 0) + 1;
                int currentMax = Math.max(Math.max(dpH[i][j], dpV[i][j]),
                                           Math.max(dpD[i][j], dpA[i][j]));
                if (currentMax > maxLen) {
                    maxLen = currentMax;
                }
            } else {
                dpH[i][j] = dpV[i][j] = dpD[i][j] = dpA[i][j] = 0;
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long absVal = Math.abs((long) n); // use long to handle Integer.MIN_VALUE
    StringBuilder sb = new StringBuilder();
    int digitCount = 0;
    while (absVal > 0) {
        sb.append(absVal % 10);
        absVal /= 10;
        digitCount++;
        if (absVal > 0 && digitCount % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }
    int n = A.length;
    java.util.Arrays.sort(A);
    boolean[] used = new boolean[n];
    java.util.Map<Long, Integer> memo = new java.util.HashMap<>();
    int fullMask = (1 << n) - 1;

    java.util.function.IntUnaryOperator isSquare = sum -> {
        int r = (int) Math.sqrt(sum);
        return r * r == sum ? 1 : 0;
    };

    java.util.function.Function<long[], Integer> dfs = new java.util.function.Function<long[], Integer>() {
        @Override
        public Integer apply(long[] params) {
            int lastIndex = (int) params[0];
            int mask = (int) params[1];
            if (mask == fullMask) {
                return 1;
            }
            long key = (((long) mask) << 32) | (lastIndex + 1L);
            Integer cached = memo.get(key);
            if (cached != null) {
                return cached;
            }
            int count = 0;
            for (int i = 0; i < n; i++) {
                if (used[i]) continue;
                if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue;
                if (lastIndex != -1 && isSquare.applyAsInt(A[lastIndex] + A[i]) == 0) continue;
                used[i] = true;
                count += apply(new long[]{i, mask | (1 << i)});
                used[i] = false;
            }
            memo.put(key, count);
            return count;
        }
    };

    return dfs.apply(new long[]{-1, 0});
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = -1;
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && currentHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int i = 0, j = 0;
    boolean up = true;
    for (int k = 0; k < m * n; k++) {
        result[k] = mat[i][j];
        if (up) {
            if (j == n - 1) {          // hit right boundary
                i++;
                up = false;
            } else if (i == 0) {       // hit top boundary
                j++;
                up = false;
            } else {                   // move up-right
                i--;
                j++;
            }
        } else {
            if (i == m - 1) {          // hit bottom boundary
                j++;
                up = true;
            } else if (j == 0) {       // hit left boundary
                i++;
                up = true;
            } else {                   // move down-left
                i++;
                j--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = Integer.toString(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no greater permutation
    }
    int j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // reverse the suffix starting at i+1
    int left = i + 1, right = digits.length - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        // result exceeds integer range
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return new ArrayList<>();
    }
    return build(n, n);
}

private static List<String> build(int currentLen, int targetLen) {
    if (currentLen == 0) {
        List<String> base = new ArrayList<>();
        base.add("");
        return base;
    }
    if (currentLen == 1) {
        List<String> base = new ArrayList<>();
        base.add("0");
        base.add("1");
        base.add("8");
        return base;
    }
    if (currentLen == 2) {
        List<String> base = new ArrayList<>();
        base.add("11");
        base.add("69");
        base.add("88");
        base.add("96");
        return base;
    }
    List<String> prev = build(currentLen - 2, targetLen);
    List<String> res = new ArrayList<>();
    for (String s : prev) {
        if (currentLen != targetLen) {
            res.add("0" + s + "0");
        }
        res.add("1" + s + "1");
        res.add("6" + s + "9");
        res.add("8" + s + "8");
        res.add("9" + s + "6");
    }
    return res;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    // Check for duplicate points
    if ((points[0][0] == points[1][0] && points[0][1] == points[1][1]) ||
        (points[0][0] == points[2][0] && points[0][1] == points[2][1]) ||
        (points[1][0] == points[2][0] && points[1][1] == points[2][1])) {
        return false;
    }
    int x0 = points[0][0], y0 = points[0][1];
    int x1 = points[1][0], y1 = points[1][1];
    int x2 = points[2][0], y2 = points[2][1];
    int area2 = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0);
    return area2 != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(Math.min(next2, next3), next5);
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    return Math.max(maxLen, currentLen);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>();
    if (n <= 0) {
        return res;
    }
    int curr = 1;
    while (res.size() < n) {
        res.add(curr);
        if (curr <= n / 10) {
            curr *= 10;
        } else if (curr % 10 != 9 && curr < n) {
            curr++;
        } else {
            curr /= 10;
            curr++;
        }
    }
    return res;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> countMap = new java.util.HashMap<>();
    for (int num : nums) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    // Initialize with a large number (n+1 is safe as the maximum needed is n)
    for (int i = 1; i <= n; i++) {
        dp[i] = n + 1;
    }
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    if (n == 0) {
        return "";
    }
    StringBuilder result = new StringBuilder(n);
    int wordStart = 0;
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            // reverse the word from wordStart to i-1
            for (int j = i - 1; j >= wordStart; j--) {
                result.append(s.charAt(j));
            }
            result.append(' ');
            wordStart = i + 1;
        }
    }
    // reverse the last word if any
    if (wordStart < n) {
        for (int j = n - 1; j >= wordStart; j--) {
            result.append(s.charAt(j));
        }
    }
    return result.toString();
}
